// 1. GET INPUTS
const webhookItem = $('Webhook: Receive Booking').first().json;
const input = webhookItem.body || webhookItem;
const room = $('DB: Get Room').first().json;
const customerData = $input.first().json;
// bookingRaw is undefined at this point (DB: Create Booking has not yet run) —
// the optional-chain falls through to `input` aliases gracefully. Same shape is
// reused by Code: Build Email Content downstream where bookingRaw IS populated.
const bookingRaw = (typeof $node !== 'undefined' && $node['DB: Create Booking']?.json) || {};

// 2. VALIDATION
if (!room || !room.data?.id) throw new Error("Room not found for id: " + (input.room_id || 'unknown'));
const customerId = customerData.data?.id;
if (!customerId) throw new Error("Customer could not be resolved: " + (customerData.message || JSON.stringify(customerData)));
if (!input.booking_date) throw new Error("booking_date missing from request.");

// 3. DEFENSIVE FINANCIAL NORMALISATION (spec'd Step C)
// Front-end / enquiry-form / calendar all may send slightly different key names.
// This fallback chain absorbs the variance so a single missing key never crashes
// the workflow or commits a zero-value booking.
const totalAmount   = parseFloat(bookingRaw?.total_amount   || bookingRaw?.total_cost   || input?.total_amount   || input?.total_cost   || 0).toFixed(2);
const balanceDue    = parseFloat(bookingRaw?.balance_due    || input?.balance_due    || totalAmount).toFixed(2);
const estimatedCost = parseFloat(bookingRaw?.estimated_cost || input?.estimated_cost || totalAmount).toFixed(2);

// 3b. NEW PARAM INTERCEPTION (Step C — defensive extraction)
// deposit_intent + additional_rooms are new fields added by enquiry-form.html
// (multi-room + Stripe-deposit isolation). Walk-in bookings from calendar.html
// don't send them. Use try/catch + fallthrough defaults so missing keys never
// throw — and the workflow continues to accept both shapes interchangeably.
let depositIntent = false;
try {
  // explicit boolean coercion so 'false' / 0 / null / undefined → false
  depositIntent = !!(input?.deposit_intent === true || input?.deposit_intent === 'true');
} catch (e) { depositIntent = false; }

let additionalRooms = [];
try {
  const raw = input?.additional_rooms;
  if (Array.isArray(raw))           additionalRooms = raw;
  else if (raw && typeof raw === 'string') {
    // tolerate stringified JSON (some n8n→db-api hops re-serialise)
    try { const parsed = JSON.parse(raw); additionalRooms = Array.isArray(parsed) ? parsed : []; }
    catch(_) { additionalRooms = []; }
  } else                            additionalRooms = [];
} catch (e) { additionalRooms = []; }


const total_amount = parseFloat(totalAmount);   // numeric, used downstream
if (isNaN(total_amount) || total_amount < 0) {
  throw new Error("Invalid total_amount received: " + (input.total_amount ?? input.total_cost));
}

const isPending = input.status === 'pending' || input.payment_type === 'none';
const pType = isPending ? 'none' : (input.payment_type === 'full' || input.payment_type === 'full_payment') ? 'full' : 'deposit';
let payment_amount = parseFloat(input.payment_amount) || 0;
if (!isPending) {
  if (isNaN(payment_amount) || payment_amount <= 0) {
    throw new Error("Invalid payment_amount received: " + input.payment_amount);
  }
}
if (pType === 'full') payment_amount = total_amount;
if (isPending) payment_amount = 0;

const balance = parseFloat(balanceDue) - (isPending || pType !== 'none' ? payment_amount : 0);
const finalBalance = total_amount - payment_amount;   // canonical: derived from validated totals
const status = isPending ? 'pending' : (finalBalance <= 0.01 ? 'fully_paid' : 'deposit_paid');

// 4. GENERATE REFS
const txnRef = 'TXN-' + Math.floor(100000 + Math.random() * 900000);
const startDateTime = input.booking_date + 'T' + input.start_time + ':00';
const endDateTime   = input.booking_date + 'T' + input.end_time   + ':00';

return {
  json: {
    ...input,
    customer_id:        customerId,
    room_id:            room.data?.id,
    // Normalised financial fields (string-form preserved as aliases for any
    // downstream consumer that expects toFixed(2) output; numeric form is the
    // canonical contract).
    total_amount:       parseFloat(total_amount.toFixed(2)),
    total_cost:         parseFloat(total_amount.toFixed(2)),   // alias for legacy consumers
    estimated_cost:     parseFloat(estimatedCost),
    payment_amount:     parseFloat(payment_amount.toFixed(2)),
    balance_due:        parseFloat(finalBalance.toFixed(2)),
    booking_status:     status,
    payment_type_clean: pType,
    payment_date:       new Date().toISOString(),
    txn_reference:      txnRef,
    request_id:         (input.request_id && input.request_id !== "") ? input.request_id : null,
    google_start:       startDateTime,
    google_end:         endDateTime,
    // New params from multi-room + Stripe-isolation enquiry forms
    deposit_intent:   depositIntent,
    additional_rooms: additionalRooms
  }
};

// ── Code: Build Email Content (Booking Confirmed) ─────────────────────────
// Mirrors the stripe_fork architecture: defensive $('NodeName').first().json
// lookups with optional chaining so the node never crashes when an upstream
// node returns an unexpected shape. Returns a passthrough object containing
// htmlBody, recipientEmail, bookingData and subject — consumed by Email: Send
// via $json.* expressions.

// ── Defensive node lookups ─────────────────────────────────────────────────
const webhookRaw  = $('Webhook: Receive Booking')?.first()?.json ?? {};
const webhookBody = webhookRaw.body ?? webhookRaw;
const customerWrap = $('DB: Upsert Customer')?.first()?.json ?? {};
const customer     = customerWrap.data ?? customerWrap;
const bookingWrap  = $('DB: Create Booking')?.first()?.json ?? {};
const booking      = bookingWrap.data ?? bookingWrap;
const logic        = $('Code: Logic + Ref')?.first()?.json ?? {};
const roomWrap     = $('DB: Get Room')?.first()?.json ?? {};
const room         = roomWrap.data ?? roomWrap;

// ── Recipient: customer table first, webhook body as fallback ──────────────
const recipientEmail = customer?.email
    || customer?.customer_email
    || webhookBody?.customer_email
    || webhookBody?.email
    || '';

const customerName = customer?.full_name
    || customer?.customer_name
    || webhookBody?.customer_name
    || 'Valued Customer';

// ── Booking details (defensive across multiple naming conventions) ─────────
const bookingId   = booking?.id || booking?.booking_id || '';
const shortRef    = bookingId ? String(bookingId).slice(0, 8).toUpperCase() : '—';
const roomName    = booking?.room_name || room?.name || logic?.room_name || webhookBody?.room_name || '—';
const bookingDate = booking?.booking_date || booking?.date_from || webhookBody?.booking_date || webhookBody?.date_from || null;
const startTime   = booking?.start_time || webhookBody?.start_time || null;
const endTime     = booking?.end_time   || webhookBody?.end_time   || null;
const totalAmount = parseFloat(booking?.total_amount ?? webhookBody?.total_amount ?? 0);
const venueName   = webhookBody?.venue_name || logic?.venue_name || customer?.tenant_name || 'VenueDesk';

// ── Formatters (mirror stripe_fork) ────────────────────────────────────────
const fmt = n => '£' + (parseFloat(n) || 0).toFixed(2);
const fmtDate = d => {
    if (!d) return '—';
    try {
        const dt = new Date(String(d).slice(0,10) + 'T00:00:00');
        return dt.toLocaleDateString('en-GB', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
    } catch(e) { return String(d); }
};
const fmtTime = t => t ? String(t).slice(0,5) : '—';

const subject = `Booking Confirmed ✓ — ${fmtDate(bookingDate)} | Ref: ${shortRef}`;

// ── HTML body: exact structure from KHvxUBua7hi5e1x1_stripe_fork.json ──────
// Header colour: Success Green (#10b981) — semantic for "Booking Confirmed".
// Accent: Indigo Primary (#6366f1). Body bg: slate-50 (#f8fafc).
// Font stack: Plus Jakarta Sans first (per spec), with system-font fallbacks
// for email clients that strip web fonts.
const FONT = "'Plus Jakarta Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif";

const htmlBody = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head>
<body style="margin:0;padding:0;background:#f8fafc;font-family:${FONT};">
  <div style="max-width:600px;margin:0 auto;padding:32px 16px;">
    <div style="background:#10b981;border-radius:12px 12px 0 0;padding:32px;text-align:center;">
      <p style="margin:0 0 6px;color:rgba(255,255,255,0.85);font-size:12px;letter-spacing:1.5px;text-transform:uppercase;">${venueName}</p>
      <h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">Booking Confirmed ✓</h1>
    </div>
    <div style="background:#ffffff;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 12px 12px;padding:32px;">
      <div style="text-align:center;margin-bottom:24px;">
        <span style="display:inline-block;background:#ecfdf5;color:#065f46;font-size:11px;font-weight:700;letter-spacing:1.5px;padding:6px 18px;border-radius:20px;">BOOKING CONFIRMED</span>
      </div>
      <p style="margin:0 0 16px;color:#1e293b;font-size:15px;">Dear <strong>${customerName}</strong>,</p>
      <p style="margin:0 0 24px;color:#374151;font-size:15px;line-height:1.7;">Thank you — your booking at <strong>${venueName}</strong> is now <strong>confirmed</strong>. The details are below; please keep this email for your records.</p>
      <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:20px;margin-bottom:16px;">
        <p style="margin:0 0 14px;color:#0f172a;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;">Booking Details</p>
        <table style="width:100%;border-collapse:collapse;font-size:14px;">
          <tr><td style="padding:5px 0;color:#64748b;width:45%;">Reference</td><td style="padding:5px 0;color:#1e293b;font-weight:600;font-family:monospace;">${shortRef}</td></tr>
          <tr><td style="padding:5px 0;color:#64748b;">Room</td><td style="padding:5px 0;color:#1e293b;font-weight:600;">${roomName}</td></tr>
          <tr><td style="padding:5px 0;color:#64748b;">Date</td><td style="padding:5px 0;color:#1e293b;font-weight:600;">${fmtDate(bookingDate)}</td></tr>
          ${(startTime || endTime) ? `<tr><td style="padding:5px 0;color:#64748b;">Time</td><td style="padding:5px 0;color:#1e293b;font-weight:600;">${fmtTime(startTime)} – ${fmtTime(endTime)}</td></tr>` : ''}
          <tr style="border-top:1px solid #e2e8f0;"><td style="padding:8px 0 5px;color:#64748b;">Total</td><td style="padding:8px 0 5px;color:#10b981;font-weight:700;">${fmt(totalAmount)}</td></tr>
        </table>
      </div>
      <div style="background:#eef2ff;border-radius:8px;padding:14px 20px;margin-bottom:28px;text-align:center;">
        <p style="margin:0;color:#64748b;font-size:12px;">Booking Reference</p>
        <p style="margin:4px 0 0;color:#6366f1;font-size:17px;font-weight:700;letter-spacing:0.5px;font-family:monospace;">${shortRef}</p>
      </div>
      <p style="margin:0;color:#64748b;font-size:13px;line-height:1.6;">Questions? Reply quoting your reference or contact <a href="mailto:bookings@venuedesk.co.uk" style="color:#6366f1;text-decoration:none;">bookings@venuedesk.co.uk</a>.</p>
    </div>
    <div style="text-align:center;padding:20px 0 0;">
      <p style="margin:0;color:#94a3b8;font-size:11px;">Automated message from VenueDesk Booking System.</p>
    </div>
  </div>
</body></html>`;

// ── Passthrough payload (spec'd shape: htmlBody + recipientEmail + bookingData) ──
return {
    json: {
        htmlBody,
        recipientEmail,
        bookingData: booking,
        subject,
        // Convenience fields so downstream nodes (audit logs, retries, etc.)
        // don't have to re-traverse upstream references.
        customer_name: customerName,
        venue_name:    venueName,
        booking_id:    bookingId,
        short_ref:     shortRef,
    }
};
